Translate the following Java 8 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353L;
    static final long INV2 = 499122177L;

    public static void main(String[] args) throws Exception {
        Reader in = new BufferedReader(new InputStreamReader(System.in));
        long n = nextLong(in);
        long m = nextLong(in);
        long l = nextLong(in);
        long r = nextLong(in);

        long d = r - l + 1;
        long nm = n * m;
        long diff = Math.abs(d % 2);

        long ans = (modPow(d, nm) + modPow(diff, nm)) % MOD;
        ans = ans * INV2 % MOD;
        if (nm % 2 == 1) ans = modPow(d, nm);
        System.out.println(ans);
    }

    static long nextLong(Reader in) throws Exception {
        int c;
        do {
            c = in.read();
        } while (c <= ' ' && c != -1);
        if (c == -1) return 0;
        boolean neg = false;
        if (c == '-') {
            neg = true;
            c = in.read();
        }
        long val = 0;
        while (c >= '0' && c <= '9') {
            val = val * 10 + (c - '0');
            c = in.read();
        }
        return neg ? -val : val;
    }

    static long modPow(long base, long exp) {
        long res = 1;
        base %= MOD;
        for (long e = exp; e > 0; e >>= 1) {
            if ((e & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
        }
        return res;
    }
}
